<?php require_once __DIR__.'/../_bootstrap.php';admin();try{if($_SERVER['REQUEST_METHOD']==='GET'){$q=db()->query("SELECT setting_value FROM app_settings WHERE setting_key='trial_days'");out(['success'=>true,'trial_days'=>(int)($q->fetch()['setting_value']??2)]);} $d=body();$days=(int)($d['trial_days']??0);if($days<0||$days>365)fail('Trial days must be between 0 and 365.');db()->prepare("INSERT INTO app_settings(setting_key,setting_value) VALUES('trial_days',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$days]);out(['success'=>true,'message'=>'Free trial days updated successfully.']);}catch(PDOException $e){error_log('WINGA settings error: '.$e->getMessage());if(str_contains($e->getMessage(),'app_settings'))fail('Trial settings table is missing. Run database/settings_migration.sql against the winga_official database.',500);throw $e;}
